body.query:
fragment repo on Repository {
	id
	databaseId
	name
	owner { login }
	sshUrl
	hasIssuesEnabled
	description
	hasWikiEnabled
	viewerPermission
	defaultBranchRef {
		name
	}
}

query RepositoryInfo($owner: String!, $name: String!) {
	repository(owner: $owner, name: $name) {
		...repo
		parent {
			...repo
		}
		mergeCommitAllowed
		rebaseMergeAllowed
		squashMergeAllowed
	}
}

query PullRequestForBranch($owner: String!, $repo: String!, $headRefName: String!, $states: [PullRequestState!]) {
	repository(owner: $owner, name: $repo) {
		pullRequests(headRefName: $headRefName, states: $states, first: 30, orderBy: { field: CREATED_AT, direction: DESC }) {
			nodes {url,id,number,state,baseRefName,headRefName,isCrossRepository,headRepositoryOwner{id,login,...on User{name}}}
		}
		defaultBranchRef { name }
	}
}

	mutation PullRequestCreate($input: CreatePullRequestInput!) {
		createPullRequest(input: $input) {
			pullRequest {
				id
				url
			}
		}
}

query PullRequestByNumber($owner: String!, $repo: String!, $pr_number: Int!) {
	repository(owner: $owner, name: $repo) {
		pullRequest(number: $pr_number) {id,author{login,...on User{id,name}},url,title,body,baseRefName,reviewRequests(first: 100) {nodes {requestedReviewer {__typename,...on User{login,name},...on Bot{login},...on Team{organization{login}name,slug}}}},labels(first:100){nodes{id,name,description,color},totalCount},milestone{number,title,description,dueOn},assignedActors(first: 10) {nodes {...on User {id,login,name,__typename}...on Bot {id,login,__typename}},totalCount},number}
	}
}
